//! 🪪️ Lossless typed numeric words, octets and ordered intrinsic containers.
use super::{FormDictionaryEntry,DslValue,FromValue,ValueError,ValueRefusalKind,NativeDecodeControl,NativeEncodeControl};
use semio_framework_value::{Number,DecodedValue};
fn invalid(message:&'static str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
pub(super) fn field<'a>(source:&'a DslValue,key:&str,keys:&[&str])->Result<&'a DslValue,ValueError>{let DslValue::Object(entries)=source else{return Err(invalid("dictionary literal record required"));};if entries.len()!=keys.len(){return Err(invalid("dictionary literal fields required"));}for key in keys{if entries.iter().filter(|(name,_)|name==key).count()!=1{return Err(invalid("duplicate or missing dictionary literal field"));}}entries.iter().find(|(name,_)|name==key).map(|(_,value)|value).ok_or_else(||invalid("dictionary literal field required"))}
enum Budget<'a,'b>{Encode(Option<&'a mut NativeEncodeControl<'b>>),Decode(Option<&'a mut NativeDecodeControl<'b>>)}
impl Budget<'_,'_>{
 fn step(&mut self)->Result<(),ValueError>{match self{Self::Encode(Some(c))=>c.step(),Self::Decode(Some(c))=>c.step(),_=>Ok(())}}
 fn allocate<T>(&mut self,count:usize)->Result<Vec<T>,ValueError>{match self{Self::Encode(Some(c))=>c.allocate_vec(count),Self::Decode(Some(c))=>c.allocate_vec(count),_=>{let mut values=Vec::new();values.try_reserve_exact(count).map_err(|_|ValueError::new(ValueRefusalKind::AllocationFailed,"dictionary literal allocation failed"))?;Ok(values)}}}
 fn text(&mut self,value:&str)->Result<String,ValueError>{match self{Self::Encode(Some(c))=>c.copy_text(value),Self::Decode(Some(c))=>c.copy_text(value),_=>Ok(value.to_string())}}
 fn push<T>(&mut self,values:&mut Vec<T>,value:T)->Result<(),(ValueError,T)>{if values.len()==values.capacity(){let count=values.capacity().max(1).checked_mul(2);let Some(count)=count else{return Err((ValueError::new(ValueRefusalKind::OwnershipLimit,"dictionary frontier overflow"),value));};let bytes=count.checked_mul(size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize);let Some(bytes)=bytes else{return Err((ValueError::new(ValueRefusalKind::OwnershipLimit,"dictionary frontier size overflow"),value));};let admission=match self{Self::Encode(Some(c))=>c.charge(bytes),Self::Decode(Some(c))=>c.charge(bytes),_=>Ok(())};if let Err(error)=admission{return Err((error,value));}if values.try_reserve_exact(count-values.len()).is_err(){return Err((ValueError::new(ValueRefusalKind::AllocationFailed,"dictionary frontier allocation failed"),value));}}values.push(value);Ok(())}
 fn object(&mut self,count:usize)->Result<DecodedValue<Vec<(String,DslValue)>>,ValueError>{Ok(DecodedValue::new(self.allocate(count)?,|values|{for(_,value)in values{<DslValue as FromValue>::retire_decoded(value)}}))}
 fn tagged<const N:usize>(&mut self,kind:&str,fields:[(&str,DslValue);N])->Result<DslValue,ValueError>{let mut fields=DecodedValue::new(fields,|fields|{for(_,value)in fields{<DslValue as FromValue>::retire_decoded(value)}});let mut values=self.object(N+1)?;values.get_mut().push((self.text("kind")?,DslValue::String(self.text(kind)?)));for index in 0..N{let name=self.text(fields.get()[index].0)?;let value=std::mem::replace(&mut fields.get_mut()[index].1,DslValue::Null);values.get_mut().push((name,value));}Ok(DslValue::Object(values.take()))}
}
enum Task<'a>{Value(&'a DslValue),Array(usize),Object(&'a[(String,DslValue)]),Members(&'a[DslValue])}
fn limb(value:&DslValue)->Result<u64,ValueError>{match value{DslValue::Number(Number::UInt(value))if*value<=u64::from(u32::MAX)=>Ok(*value),DslValue::Number(Number::Int(value))if*value>=0&&*value<=i64::from(u32::MAX)=>Ok(*value as u64),_=>Err(invalid("dictionary numeric limb required"))}}
fn word(value:&DslValue)->Result<u64,ValueError>{let keys=["kind","high","low"];Ok((limb(field(value,"high",&keys)?)?<<32)|limb(field(value,"low",&keys)?)?)}
fn finish(values:&mut DecodedValue<Vec<DslValue>>,count:usize,budget:&mut Budget<'_,'_>)->Result<Vec<DslValue>,ValueError>{let start=values.get().len().checked_sub(count).ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"dictionary value frontier underflow"))?;let mut children=Vec::<DslValue>::guard_decoded(budget.allocate(count)?);for index in start..values.get().len(){budget.step()?;children.get_mut().push(std::mem::replace(&mut values.get_mut()[index],DslValue::Null));}values.get_mut().truncate(start);Ok(children.take())}
fn literal(source:&DslValue,encode:bool,budget:&mut Budget<'_,'_>)->Result<DslValue,ValueError>{
 let mut pending=Vec::new();budget.push(&mut pending,Task::Value(source)).map_err(|(error,_)|error)?;let mut values=Vec::<DslValue>::guard_decoded(Vec::new());
 while let Some(task)=pending.pop(){budget.step()?;let value=match task{
  Task::Value(value)if encode=>match value{
   DslValue::Null=>Some(budget.tagged("null",[])?),
   DslValue::Bool(value)=>Some(budget.tagged("boolean",[("value",DslValue::Bool(*value))])?),
   DslValue::Number(value)=>{let(kind,word)=match value{Number::UInt(value)=>("unsigned",*value),Number::Int(value)=>("signed",*value as u64),Number::Float(value)=>("float",value.to_bits())};Some(budget.tagged(kind,[("high",DslValue::uint(word>>32)),("low",DslValue::uint(word&0xffffffff))])?)},
   DslValue::String(value)=>{let text=budget.text(value)?;Some(budget.tagged("text",[("value",DslValue::String(text))])?)},
   DslValue::Bytes(bytes)=>{let mut output=Vec::<DslValue>::guard_decoded(budget.allocate(bytes.len())?);for byte in bytes{output.get_mut().push(DslValue::uint(u64::from(*byte)));budget.step()?;}Some(budget.tagged("bytes",[("value",DslValue::Array(output.take()))])?)},
   DslValue::Array(items)=>{budget.push(&mut pending,Task::Array(items.len())).map_err(|(error,_)|error)?;for value in items.iter().rev(){budget.push(&mut pending,Task::Value(value)).map_err(|(error,_)|error)?;}None},
   DslValue::Object(members)=>{budget.push(&mut pending,Task::Object(members)).map_err(|(error,_)|error)?;for(_,value)in members.iter().rev(){budget.push(&mut pending,Task::Value(value)).map_err(|(error,_)|error)?;}None}
  },
  Task::Value(source)=>{let kind=match source{DslValue::Object(entries)=>entries.iter().find(|(name,_)|name=="kind").and_then(|(_,value)|value.as_str()).ok_or_else(||invalid("dictionary value kind required"))?,_=>return Err(invalid("dictionary value record required"))};match kind{
   "null"=>{field(source,"kind",&["kind"])?;Some(DslValue::Null)},
   "boolean"=>{let value=field(source,"value",&["kind","value"])?;let DslValue::Bool(value)=value else{return Err(invalid("dictionary boolean required"));};Some(DslValue::Bool(*value))},
   "unsigned"=>Some(DslValue::uint(word(source)?)),"signed"=>Some(DslValue::int(word(source)?as i64)),"float"=>Some(DslValue::float(f64::from_bits(word(source)?))),
   "text"=>{let value=field(source,"value",&["kind","value"])?.as_str().ok_or_else(||invalid("dictionary text required"))?;Some(DslValue::String(budget.text(value)?))},
   "bytes"=>{let value=field(source,"value",&["kind","value"])?;let DslValue::Array(values)=value else{return Err(invalid("dictionary octets required"));};let mut bytes=budget.allocate(values.len())?;for value in values{bytes.push(u8::try_from(limb(value)?).map_err(|_|invalid("dictionary octet range"))?);budget.step()?;}Some(DslValue::Bytes(bytes))},
   "array"=>{let DslValue::Array(items)=field(source,"items",&["kind","items"])? else{return Err(invalid("dictionary array required"));};budget.push(&mut pending,Task::Array(items.len())).map_err(|(error,_)|error)?;for value in items.iter().rev(){budget.push(&mut pending,Task::Value(value)).map_err(|(error,_)|error)?;}None},
   "object"=>{let DslValue::Array(members)=field(source,"members",&["kind","members"])? else{return Err(invalid("dictionary members required"));};budget.push(&mut pending,Task::Members(members)).map_err(|(error,_)|error)?;for member in members.iter().rev(){budget.push(&mut pending,Task::Value(field(member,"value",&["name","value"])?)).map_err(|(error,_)|error)?;}None},
   _=>return Err(invalid("unknown dictionary value kind"))
  }},
  Task::Array(count)=>{let children=finish(&mut values,count,budget)?;Some(if encode{budget.tagged("array",[("items",DslValue::Array(children))])?}else{DslValue::Array(children)})},
  Task::Object(members)=>{let mut children=Vec::<DslValue>::guard_decoded(finish(&mut values,members.len(),budget)?);let mut output=Vec::<DslValue>::guard_decoded(budget.allocate(members.len())?);for(index,(name,_))in members.iter().enumerate(){let mut member=budget.object(2)?;member.get_mut().push((budget.text("name")?,DslValue::String(budget.text(name)?)));let key=budget.text("value")?;let value=std::mem::replace(&mut children.get_mut()[index],DslValue::Null);member.get_mut().push((key,value));output.get_mut().push(DslValue::Object(member.take()));budget.step()?;}Some(budget.tagged("object",[("members",DslValue::Array(output.take()))])?)},
  Task::Members(members)=>{let mut children=Vec::<DslValue>::guard_decoded(finish(&mut values,members.len(),budget)?);let mut output=budget.object(members.len())?;for(index,member)in members.iter().enumerate(){let name=field(member,"name",&["name","value"])?.as_str().ok_or_else(||invalid("dictionary member name required"))?;let name=budget.text(name)?;let value=std::mem::replace(&mut children.get_mut()[index],DslValue::Null);output.get_mut().push((name,value));budget.step()?;}Some(DslValue::Object(output.take()))}
 };if let Some(value)=value{if let Err((error,value))=budget.push(values.get_mut(),value){<DslValue as FromValue>::retire_decoded(value);return Err(error);}}}
 values.get_mut().pop().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"dictionary value frontier empty"))
}
fn encode(entry:&FormDictionaryEntry,budget:&mut Budget<'_,'_>)->Result<DslValue,ValueError>{let mut fields=budget.object(2)?;fields.get_mut().push((budget.text("questionId")?,DslValue::String(budget.text(&entry.question_id)?)));let value=literal(&entry.value,true,budget)?;fields.get_mut().push((budget.text("value")?,value));Ok(DslValue::Object(fields.take()))}
fn decode(value:&DslValue,budget:&mut Budget<'_,'_>)->Result<FormDictionaryEntry,ValueError>{let keys=["questionId","value"];let question_id=field(value,"questionId",&keys)?.as_str().ok_or_else(||invalid("dictionary question identity required"))?;let question_id=budget.text(question_id)?;let value=literal(field(value,"value",&keys)?,false,budget)?;Ok(FormDictionaryEntry{question_id,value})}
pub(super) fn entry_encode(entry:&FormDictionaryEntry,control:Option<&mut NativeEncodeControl<'_>>)->Result<DslValue,ValueError>{match control{Some(control)=>control.scoped_stage(|control|{control.begin_stage(0)?;encode(entry,&mut Budget::Encode(Some(control)))}),None=>encode(entry,&mut Budget::Encode(None))}}
pub(super) fn entry_decode(value:&DslValue,control:Option<&mut NativeDecodeControl<'_>>)->Result<FormDictionaryEntry,ValueError>{match control{Some(control)=>control.scoped_stage(|control|{control.begin_stage(0)?;decode(value,&mut Budget::Decode(Some(control)))}),None=>decode(value,&mut Budget::Decode(None))}}
